/* ============================================================
   أطياب الجاسم (React) — ملخّص المنتجات (SummaryProduct)

   كومبوننت واحد بوضعين، كما طُلب:
     mode="trolley"  → ملخّص الفاتورة: المجموع الفرعي، خصم العروض،
                       الكوبون، الشحن، الضريبة المضمّنة، الإجمالي،
                       ومقدار التوفير + زر «إرسال الفاتورة».
     mode="wishlist" → ملخّص قائمة الأمنيات: عدد المنتجات، القيمة، التوفير،
                       وزرّ «أضف كل القطع للعربة» + روابط سريعة.

   ★ الأرقام كلها من selectors.js (مصدر واحد للحساب) — لا حساب هنا.
   ============================================================ */

import { Link, useNavigate } from "react-router-dom";
import { PATHS } from "../../routes.js";
import { COUPONS } from "../../redux/slices/cartSlice.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { selectCartTotals, selectWishlistProducts, unitPriceOf, FREE_SHIP_OVER, FREE_SHIP_OVER_GCC, SHIP_FEE } from "../../redux/selectors.js";
import { addItem } from "../../redux/slices/cartSlice.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { Money } from "../Source/Money.jsx";
import { Icon } from "../Source/Icons.jsx";

export default function SummaryProduct(props) {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const totals = useAppSelector(selectCartTotals);
  const wishlist = useAppSelector(selectWishlistProducts);
  const invoiceNo = useAppSelector(function (s) {
    return s.cart.invoiceNo;
  });
  const session = useAppSelector(function (s) {
    return s.user.session;
  });

  function goToCheckout() {
    /* ★ الزائر → الدخول/التسجيل أولاً ثم عودة تلقائية إلى إتمام الدفع */
    if (!session) {
      navigate(PATHS.login, { state: { from: PATHS.checkout } });
      return;
    }
    navigate(PATHS.checkout);
  }

  if (props.mode === "wishlist") {
    const before = wishlist.reduce(function (sum, p) {
      return sum + (p.oldPrice || unitPriceOf(p));
    }, 0);
    const net = wishlist.reduce(function (sum, p) {
      return sum + unitPriceOf(p);
    }, 0);
    const saved = Math.max(0, before - net);
    return (
      <div className="ct-card wl-sum">
        <div className="ct-inv-head">
          <div>
            <span className="ct-inv-kicker">ملخّص</span>
            <h3>قائمة الأمنيات</h3>
          </div>
          <span className="ct-inv-no" title="عدد المنتجات المحفوظة">
            <b>♥</b>
            {wishlist.length}
          </span>
        </div>

        <ul className="ct-lines">
          <li>
            <span>عدد المنتجات</span>
            <b>{wishlist.length}</b>
          </li>
          <li className="is-vat">
            <span>القيمة الإجمالية</span>
            <b>
              <Money sar={before} />
            </b>
          </li>
          {saved > 0 ? (
            <li className="is-cut">
              <span>مجموع التوفير</span>
              <b>
                − <Money sar={saved} />
              </b>
            </li>
          ) : null}
        </ul>

        <div className="ct-total" role="status" aria-live="polite">
          <span>{saved > 0 ? "التكلفة بعد العروض" : "التكلفة"}</span>
          <b>
            <Money sar={net} />
          </b>
        </div>

        {saved > 0 ? (
          <p className="ct-saved">
            <Icon name="spark" />
            <span>
              وفّرت من هذه القائمة <b><Money sar={saved} /></b>
            </span>
          </p>
        ) : null}

        <button
          className="wl-add-all"
          type="button"
          disabled={!wishlist.length}
          onClick={function () {
            if (!wishlist.length) {
              dispatch(uiActions.toastShown("القائمة فارغة"));
              return;
            }
            wishlist.forEach(function (p) {
              dispatch(addItem(p.id, 1));
            });
            dispatch(uiActions.toastShown("أُضيفت كل القطع (" + wishlist.length + ") إلى العربة"));
          }}
        >
          <Icon name="cart" />
          <span>أضف كل القطع للعربة</span>
        </button>

        <div className="wl-links">
          <Link to={PATHS.perfumes} className="wl-link">العطور</Link>
          <Link to={PATHS.incense} className="wl-link">البخور</Link>
          <Link to={PATHS.profile} className="wl-link">حسابي</Link>
        </div>

        <p className="wl-hint">
          <Icon name="info" strokeWidth={1.8} />
          <span>
            الأسعار قبل الشحن والضريبة — تظهر كاملة في{" "}
            <Link to={PATHS.cart}>عربة التسوق</Link>
            .
          </span>
        </p>
      </div>
    );
  }

  /* ---------- وضع السلة: الفاتورة ---------- */
  return (
    <div className="ct-card ct-invoice">
      <div className="ct-inv-head">
        <div>
          <span className="ct-inv-kicker">الفاتورة</span>
          <h3>معلومات الفاتورة</h3>
        </div>
        <span className="ct-inv-no" title="رقم الفاتورة">
          <b>#</b>
          {invoiceNo}
        </span>
      </div>

      <ul className="ct-lines">
        <li>
          <span>المجموع الفرعي ({totals.count} قطعة)</span>
          <b>
            <Money sar={totals.before} />
          </b>
        </li>
        {totals.offerSave > 0 ? (
          <li className="is-cut">
            <span>خصم العروض</span>
            <b>
              − <Money sar={totals.offerSave} />
            </b>
          </li>
        ) : null}
        {totals.discount > 0 ? (
          <li className="is-cut">
            <span>
              كوبون {totals.code} ({totals.percent}%)
            </span>
            <b>
              − <Money sar={totals.discount} />
            </b>
          </li>
        ) : null}
        <li>
          <span>
            الشحن {totals.shipFree ? <em className="ct-free">مجاني</em> : null}
          </span>
          <b>
            <Money sar={totals.shipping} />
          </b>
        </li>
        <li className="is-vat">
          <span>
            ضريبة القيمة المضافة {Math.round(((totals.vatRate == null ? 0.05 : totals.vatRate)) * 100)}% {totals.vatIncluded !== false ? <em>مضمّنة</em> : <em>تُضاف</em>}
          </span>
          <b>
            <Money sar={totals.vat} />
          </b>
        </li>
      </ul>

      <div className="ct-total" role="status" aria-live="polite">
        <span>الإجمالي</span>
        <b>
          <Money sar={totals.total} />
        </b>
      </div>

      {totals.saved > 0 ? (
        <p className="ct-saved">
          <Icon name="spark" />
          <span>
            وفّرت في هذه الفاتورة <b><Money sar={totals.saved} /></b>
          </span>
        </p>
      ) : null}

      {!totals.shipFree && totals.toFreeShip > 0 ? (
        <p className="ct-ship-note">
          <Icon name="info" strokeWidth={1.8} />
          <span>
            أضف بقيمة <b><Money sar={totals.toFreeShip} /></b> للحصول على شحن مجاني.
          </span>
        </p>
      ) : null}

      {/* ★ لا زرّ «إرسال الفاتورة» هنا: الفاتورة تُصدر في صفحة إتمام الدفع
         بعد تأكيد الطلب، ووجود الزر في العربة كان يوهم العميل بأن الطلب
         أُرسل قبل أن يدفع. زرّ المتابعة الوحيد هو «إتمام الدفع» في بطاقة
         طريقة الدفع أسفل هذه الفاتورة. */}

      {/* ★ زرّ إتمام الدفع مدمج مع الفاتورة نفسها: لا كوبون ولا اختيار
         طريقة هنا — الكوبون والطريقة في خطوة الدفع داخل Checkout. */}
      <button className="btn-primary ct-pay-btn" type="button" onClick={goToCheckout}>
        <Icon name="lock" strokeWidth={1.8} />
        <span>إتمام الدفع</span>
      </button>

      <p className="ct-secure">
        <Icon name="shield" />
        <span>
          شحن مجاني فوق <Money sar={FREE_SHIP_OVER} /> داخل الإمارات · وفوق <Money sar={FREE_SHIP_OVER_GCC} /> للخليج · قيمة الشحن <Money sar={SHIP_FEE} />{Object.keys(COUPONS).length ? <span> · الكوبونات المتاحة: {Object.keys(COUPONS).join(" · ")}</span> : null}
        </span>
      </p>
    </div>
  );
}
