/* ============================================================
   أطياب الجاسم (React) — بطاقة القائمة (ListProductCard)

   كومبوننت واحد بوضعين — كما طُلب:
     mode="trolley"   → وضع السلة: صورة + معلومات + نسبة الخصم + اسم العرض
                        + زرّا (− / +) للكمية + الحذف + إجمالي السطر.
     mode="wishlist"  → وضع قائمة الأمنيات: شارة «في العربة» + حالة المخزون
                        + «أضف للعربة» + «إزالة» (بلا عدّاد كمية).

   ★ يُستعمل في TrolleyPage و WishlistPage فقط — والبيانات من Redux.
   ============================================================ */

import { useRef } from "react";
import { Link } from "react-router-dom";
import { productPath } from "../../routes.js";
import { ATYAB_catalogOf } from "../../data/products.js";
import { productName, productSize, productKind, tr2 } from "../../i18n.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { stepItem, removeItem, addItem } from "../../redux/slices/cartSlice.js";
import { removeWish } from "../../redux/slices/wishlistSlice.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { flyFromButton } from "../../utils/flyToCart.js";
import { unitPriceOf } from "../../redux/selectors.js";
import { Money } from "../Source/Money.jsx";
import { Icon, ProductImage } from "../Source/Icons.jsx";

function collectionLabel(p, lang) {
  const cat = ATYAB_catalogOf ? ATYAB_catalogOf(p.id) : null;
  const list = (cat && cat.collections) || [];
  for (let i = 0; i < list.length; i++) {
    if (list[i].key === p.collection) return tr2(lang, list[i].labelEn || list[i].label, list[i].label);
  }
  return tr2(lang, (cat && cat.collectionFallbackEn) || "Our perfumes", (cat && cat.collectionFallback) || "عطورنا");
}

function stockLabel(p) {
  const stock = typeof p.stock === "number" ? p.stock : 10;
  if (stock <= 0) return <span className="ct-badge wl-stock is-out">نفد المخزون</span>;
  if (stock <= 5) return <span className="ct-badge wl-stock is-low">آخر {stock} قطع</span>;
  return <span className="ct-badge wl-stock is-ok">متوفر الآن</span>;
}

export default function ListProductCard(props) {
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const p = props.product;
  const qty = Number(props.qty) || 1;
  const trolley = props.mode === "trolley";
  /* ★ حارس النقرة المزدوجة — قبل أي return مبكر (قانون React) */
  const lastTap = useRef(0);
  if (!p) return null;

  const unit = unitPriceOf(p);
  const lineTotal = unit * qty;
  const lineOld = (p.oldPrice || unit) * qty;
  const pct = p.oldPrice && p.oldPrice > unit ? Math.round(((p.oldPrice - unit) / p.oldPrice) * 100) : 0;
  const savings = Math.max(0, lineOld - lineTotal);
  const name = productName(p, language);
  const meta = [productSize(p, language), productKind(p, language), collectionLabel(p, language)].filter(Boolean).join(" · ");
  function guardedAdd(btn) {
    const at = Date.now();
    if (at - (lastTap.current || 0) < 800) return false;
    lastTap.current = at;
    /* ★ R9: طيران البطاقة إلى العربة — يُقرأ قبل إعادة الرسم */
    try {
      flyFromButton(btn || null, "cart");
    } catch (e) {}
    dispatch(addItem(p.id, 1));
    return true;
  }

  return (
    <article className="ct-item" data-id={p.id}>
      <Link
        className="ct-thumb"
        to={productPath(p.id)}
        aria-label={tr2(language, "View details of " + name, "عرض تفاصيل " + name)}
      >
        <ProductImage product={p} />
        {p.offer ? <span className="ct-thumb-off">{tr2(language, p.offerEn || p.offer, p.offer)}</span> : null}
      </Link>

      <div className="ct-body">
        <div className="ct-line1">
          <h3 className="ct-name">
            <Link to={productPath(p.id)}>{name}</Link>
          </h3>
          {!trolley && props.inCart ? (
            <span className="wl-incart">
              <Icon name="check" strokeWidth={2.1} />
              في العربة
            </span>
          ) : null}
          {trolley && p.offer ? <span className="ct-offer">{tr2(language, p.offerEn || p.offer, p.offer)}</span> : null}
        </div>

        <p className="ct-meta">{meta}</p>

        <div className="ct-badges">
          {pct > 0 ? <span className="ct-badge ct-badge-pct">نسبة الخصم {pct}%</span> : null}
          {savings > 0 ? (
            <span className="ct-badge ct-badge-save">
              توفير <Money sar={savings} />
            </span>
          ) : null}
          {/* ★ رفض الخادم لهذا الصف (404 منتج/مخزون): نصّ الخادم نفسه */}
          {trolley && props.note ? (
            <span className="ct-badge wl-stock is-out" title={String(props.note)}>
              الخادم: {String(props.note).slice(0, 90)}
            </span>
          ) : null}
          {trolley ? (
            <span className="ct-badge ct-badge-plain">
              سعر القطعة <Money sar={unit} />
            </span>
          ) : (
            stockLabel(p)
          )}
        </div>

        <div className="ct-actions">
          {trolley ? (
            <div className="ct-qty" role="group" aria-label={tr2(language, "Quantity of " + name, "كمية " + name)}>
              <button
                type="button"
                aria-label="تقليل الكمية (أو الحذف عند الوصول لواحد)"
                disabled={qty <= 1}
                onClick={function () {
                  dispatch(stepItem(p.id, -1));
                }}
              >
                −
              </button>
              <input type="text" inputMode="numeric" value={qty} readOnly aria-label="الكمية" />
              <button
                type="button"
                aria-label="زيادة الكمية"
                onClick={function () {
                  dispatch(stepItem(p.id, 1));
                }}
              >
                +
              </button>
            </div>
          ) : (
            <button
              className="wl-add"
              type="button"
              onClick={function (e) {
                guardedAdd(e.currentTarget);
              }}
            >
              <Icon name="cart" />
              <span>{props.inCart ? "أضف المزيد" : "أضف للعربة"}</span>
            </button>
          )}

          <div className="ct-money">
            <span className="ct-line-total">
              <Money sar={trolley ? lineTotal : unit} />
            </span>
            {(trolley ? lineOld > lineTotal : savings > 0) ? (
              <span className="ct-line-old">
                <Money sar={trolley ? lineOld : p.oldPrice || unit} />
              </span>
            ) : null}
          </div>

          <button
            className="ct-remove"
            type="button"
            aria-label={tr2(language, "Remove " + name, "إزالة " + name)}
            title={trolley ? "حذف من العربة" : "إزالة من قائمة الأمنيات"}
            onClick={function () {
              if (trolley) {
                dispatch(removeItem(p.id));
                return;
              }
              dispatch(removeWish(p.id));
              dispatch(uiActions.toastShown(tr2(language, "Removed «" + name + "» from the wishlist", "أُزيل «" + name + "» من قائمة الأمنيات")));
            }}
          >
            <Icon name="trash" strokeWidth={1.8} />
            <span>{trolley ? "حذف" : "إزالة"}</span>
          </button>
        </div>
      </div>
    </article>
  );
}
